// The two DOT rows of keyedreach that have no static lowering: `a.reduce(...)`
// and `a.flat()` on a checked-dynamic array. They live in their own package
// because a refused function poisons the whole module that holds it, and
// keyedreach is a program that must build.
"use strict";
function t(f) { try { return String(f()); } catch (e) { return "THREW " + String(e.message); } }
function darr() { return JSON.parse("[1,2,3]"); }
exports.tReduce  = function () { var a = darr(); return t(function () { return a.reduce(function (x, y) { return x + y; }, 0); }); };
exports.tFlat    = function () { var a = darr(); return t(function () { return a.flat(); }); };
